import { StyleSheet, } from 'react-native';

const styles = StyleSheet.create({
    container: {
        backgroundColor: 'rgba(50,50,50,0.7)',
        flexDirection: 'row',
        borderRadius: 12,
        alignItems: 'center',
        justifyContent: 'space-around',
        width: 115,
        marginHorizontal: 5,
        height: 30,
    },


    listText: {
        fontSize: 40,
        color: '#000',
        backgroundColor: '#fff',
        padding: 5,
        borderRadius: 10,
        margin: 20

    },

    input: {
        textAlign: 'center',
        textAlignVertical: 'center',
        minHeight: 40,
        fontSize: 17,
        borderColor: '#708090',
        borderWidth: 2,
        backgroundColor: '#356',
        borderRadius: 10,
        color: '#fff'
    },

    payText: {
        color: '#fff',
        fontSize: 30,
        textAlign: 'center'
    },

    buttonPay: {
        backgroundColor: '#26A744',
        borderRadius: 15,
        width: '100%',
        padding: 10,
        marginTop: 15,
    }

});
export { styles };
